WITH department_totals AS (SELECT dept_id, ROUND((100 * SUM(CASE WHEN level = 'L3' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_l3, MAX(hire_date) AS last_hire_date FROM employees WHERE job_title != 'Director' GROUP BY dept_id) SELECT d.id, d.location, d.dept_name, dt.pct_l3, dt.last_hire_date FROM departments d JOIN department_totals dt ON d.id = dt.dept_id WHERE dt.pct_l3 >= 68 ORDER BY last_hire_date
